import { createHash } from "node:crypto";
import { DeleteObjectCommand, GetObjectCommand, HeadObjectCommand, PutObjectCommand, S3Client } from "@aws-sdk/client-s3";

// Private object storage (SYSTEM_DESIGN.md: private Cloudflare R2 via the S3 API). Keys are generated by the server;
// nothing here is publicly readable — bytes reach browsers only through the media gateway with a grant.

export type StoredObject = { bytes: number; contentType: string; etag: string | null };
export type ByteRange = { start: number; end: number }; // inclusive
export type ObjectBody = { stream: ReadableStream<Uint8Array>; bytes: number };

export interface ObjectStore {
  put(key: string, body: Buffer, contentType: string): Promise<void>;
  head(key: string): Promise<StoredObject | null>;
  get(key: string, range?: ByteRange): Promise<ObjectBody | null>;
  delete(key: string): Promise<void>;
}

export type R2Config = { accountId: string; accessKeyId: string; secretAccessKey: string; bucket: string };

export function readR2Config(env: Record<string, string | undefined> = process.env): R2Config | null {
  const accountId = env.R2_ACCOUNT_ID?.trim();
  const accessKeyId = env.R2_ACCESS_KEY_ID?.trim();
  const secretAccessKey = env.R2_SECRET_ACCESS_KEY?.trim();
  const bucket = env.R2_BUCKET?.trim();
  if (!accountId || !accessKeyId || !secretAccessKey || !bucket) return null;
  if (!/^[a-f0-9]{32}$/.test(accountId)) throw new Error("R2_ACCOUNT_ID must be the 32-character Cloudflare account ID.");
  return { accountId, accessKeyId, secretAccessKey, bucket };
}

const notFound = (error: unknown) => {
  const e = error as { name?: string; $metadata?: { httpStatusCode?: number } };
  return e?.name === "NoSuchKey" || e?.name === "NotFound" || e?.$metadata?.httpStatusCode === 404;
};

export class R2ObjectStore implements ObjectStore {
  private readonly client: S3Client;
  constructor(private readonly config: R2Config) {
    this.client = new S3Client({
      region: "auto",
      endpoint: `https://${config.accountId}.r2.cloudflarestorage.com`,
      credentials: { accessKeyId: config.accessKeyId, secretAccessKey: config.secretAccessKey },
    });
  }

  async put(key: string, body: Buffer, contentType: string) {
    await this.client.send(new PutObjectCommand({ Bucket: this.config.bucket, Key: key, Body: body, ContentType: contentType, ContentLength: body.length }));
  }

  async head(key: string): Promise<StoredObject | null> {
    try {
      const r = await this.client.send(new HeadObjectCommand({ Bucket: this.config.bucket, Key: key }));
      return { bytes: Number(r.ContentLength ?? 0), contentType: r.ContentType ?? "application/octet-stream", etag: r.ETag?.replaceAll('"', "") ?? null };
    } catch (error) {
      if (notFound(error)) return null;
      throw error;
    }
  }

  async get(key: string, range?: ByteRange): Promise<ObjectBody | null> {
    try {
      const r = await this.client.send(
        new GetObjectCommand({ Bucket: this.config.bucket, Key: key, ...(range ? { Range: `bytes=${range.start}-${range.end}` } : {}) }),
      );
      if (!r.Body) return null;
      return { stream: r.Body.transformToWebStream() as ReadableStream<Uint8Array>, bytes: Number(r.ContentLength ?? 0) };
    } catch (error) {
      if (notFound(error)) return null;
      throw error;
    }
  }

  async delete(key: string) {
    await this.client.send(new DeleteObjectCommand({ Bucket: this.config.bucket, Key: key }));
  }
}

/** In-memory store with the same semantics (ETag = MD5 like single-part R2 uploads). Used by tests. */
export class MemoryObjectStore implements ObjectStore {
  readonly objects = new Map<string, { body: Buffer; contentType: string }>();
  async put(key: string, body: Buffer, contentType: string) {
    this.objects.set(key, { body: Buffer.from(body), contentType });
  }
  async head(key: string) {
    const o = this.objects.get(key);
    return o ? { bytes: o.body.length, contentType: o.contentType, etag: createHash("md5").update(o.body).digest("hex") } : null;
  }
  async get(key: string, range?: ByteRange) {
    const o = this.objects.get(key);
    if (!o) return null;
    const chunk = range ? o.body.subarray(range.start, range.end + 1) : o.body;
    return { stream: new Blob([new Uint8Array(chunk)]).stream(), bytes: chunk.length };
  }
  async delete(key: string) {
    this.objects.delete(key);
  }
}

const cache = globalThis as typeof globalThis & { __namasteStore?: ObjectStore };

/** The configured object store, or null when storage is not configured (features then report unavailable). */
export function getObjectStore(): ObjectStore | null {
  if (cache.__namasteStore) return cache.__namasteStore;
  const config = readR2Config();
  if (!config) return null;
  cache.__namasteStore = new R2ObjectStore(config);
  return cache.__namasteStore;
}

export function setObjectStoreForTests(store: ObjectStore | undefined) {
  cache.__namasteStore = store;
}
